// Carousel
// *******************************************************************************

.carousel {
  .carousel-item.active,
  .carousel-item.carousel-item-start {
    h1,
    .h1,
    h2,
    .h2,
    h3,
    .h3,
    h4,
    .h4,
    h5,
    .h5,
    h6,
    .h6 {
      color: $carousel-caption-color;
    }
  }
}

.carousel.carousel-dark {
  .carousel-item,
  .carousel-item.active,
  .carousel-item.carousel-item-start {
    h1,
    .h1,
    h2,
    .h2,
    h3,
    .h3,
    h4,
    .h4,
    h5,
    .h5,
    h6,
    .h6 {
      color: $carousel-dark-caption-color;
    }
  }
}

[data-bs-theme="dark"] {
  .carousel:not(.carousel-dark) .carousel-caption,
  &.carousel:not(.carousel-dark) .carousel-caption {
    color: $carousel-caption-color;
  }
}
