// HaramApp Custom Styles & Utilities
// *******************************************************************************

// Navbar icon buttons - ensure proper border-radius
.navbar-nav {
  .btn-icon,
  .nav-link.btn-icon {
    @include border-radius($border-radius-xs);
  }

  .dropdown-language .nav-link,
  .dropdown .nav-link,
  .dropdown-notifications .nav-link,
  .navbar-search-wrapper {
    @include border-radius($border-radius-xs);
  }
}

// Fix hover state background for navbar buttons
.navbar-nav .nav-item {
  .nav-link.btn-icon:hover,
  .nav-link.btn-icon:focus {
    @include border-radius($border-radius-xs);
  }
}

// HaramApp Standard Border-Radius Utilities
.rounded-xs {
  @include border-radius($border-radius-xs); // 8px
}

.rounded-standard {
  @include border-radius($border-radius-sm); // 12px
}

// Ensure all buttons use 8px border-radius - override CSS variables with !important
.btn,
.btn-sm,
.btn-group-sm > .btn,
.btn-primary,
.btn-gold {
  @include border-radius($border-radius-xs);
  border-radius: $border-radius-xs !important;
}

// Form controls use 8px border-radius (already set in variables, but enforce here)
.form-control,
.form-select {
  @include border-radius($border-radius-xs);
}

// Input group components
.input-group-text {
  @include border-radius($border-radius-xs);
}

.input-group-merge {
  @include border-radius($border-radius-xs);

  .form-control {
    border-radius: 0 $border-radius-xs $border-radius-xs 0;
  }

  .input-group-text {
    border-radius: $border-radius-xs 0 0 $border-radius-xs;
  }

  &:focus-within {
    @include border-radius($border-radius-xs);
  }
}

// Dropdown menus
.dropdown-menu {
  @include border-radius($border-radius-sm); // 12px for dropdowns
}

// Dropdown items
.dropdown-item {
  @include border-radius($border-radius-xs); // 8px for dropdown items
}
